t4*       0.95619334     (L4)

t5*       0.99262276     (L5)     ;

I by t0@1

t1@1

t2@1

t3@1

t4@1

t5@1   ;

[t0*] (int0);

[t1*] (int1);

[t2*] (int2);

[t3*] (int3);

[t4*] (int4);

[t5*] (int5);

t0*       0.052631579   ;

t1*       0.052631579   ;

